package com.erp.reimbursement.dto;
import jakarta.validation.constraints.*; import java.time.*; import com.erp.reimbursement.enums.Role;
public final class AuthDtos { private AuthDtos(){} public record LoginRequest(@NotBlank String email,@NotBlank String password,@NotNull Role role){} public record LoginResponse(String token,String username,String role,String employeeId,String name,String firstName,String lastName,String email,String department,String designation){} public record SignupRequest(@NotBlank @Email String email,@NotBlank String password,@NotBlank String employeeId,@NotBlank String firstName,@NotBlank String lastName,@NotNull LocalDate dateOfBirth,@NotBlank String department,@NotBlank @Pattern(regexp="[6-9]\\d{9}") String mobile,String alternateMobile){} public record OtpRequest(@NotBlank @Email String email,@NotBlank @Pattern(regexp="[6-9]\\d{9}") String mobile){} public record VerifyOtpRequest(@NotBlank @Email String email,@NotBlank String otp){} public record ResetPasswordRequest(@NotBlank @Email String email,@NotBlank String otp,@NotBlank String newPassword){} }
